style.css:
@-moz-document domain("youtube.com") {
/* MAIN YOUTUBE BACKGROUND */

    html,
    body {
        background-image: url("https://i.pinimg.com/736x/1a/00/f7/1a00f7de91dd2050029439e8c4806df2.jpg") !important;
        background-size: cover !important;
        background-position: center 15% !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }


    /* MAIN CONTENT */

    ytd-app,
    #page-manager,
    ytd-browse,
    #content,
    #primary,
    #secondary,
    #contentContainer,
    ytd-rich-grid-renderer,
    ytd-rich-grid-renderer #contents {
        background: transparent !important;
    }


    /* YOUTUBE HEADER */

    #masthead-container,
    ytd-masthead,
    #background.ytd-masthead {
        background: transparent !important;
        background-image: none !important;
    }


    /* SEARCH BAR */

    ytd-searchbox,
    #search-form,
    #container.ytd-searchbox,
    ytd-searchbox #container {
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
    }


    /* CATEGORY / CHIP BAR */

    #frosted-glass,
    #frosted-glass.with-chipbar,
    #frosted-glass.ytd-app,
    ytd-feed-filter-chip-bar-renderer,
    ytd-feed-filter-chip-bar-renderer #chips-wrapper,
    ytd-feed-filter-chip-bar-renderer #scroll-container {
        background: transparent !important;
        background-color: transparent !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
    }


    /* SIDEBAR */

    ytd-mini-guide-renderer,
    ytd-guide-renderer,
    #guide-content,
    #guide-inner-content,
    #sections {
        background: transparent !important;
    }


    /* ALL YOUTUBE TEXT */

    yt-formatted-string,
    #video-title,
    #channel-name,
    #text,
    yt-chip-cloud-chip-renderer,
    yt-chip-cloud-chip-renderer #text,
    ytd-guide-entry-renderer #text,
    ytd-guide-entry-renderer yt-formatted-string,
    ytd-rich-grid-media #video-title,
    ytd-rich-grid-media #channel-name,
    ytd-video-meta-block,
    ytd-video-meta-block #metadata-line,
    #metadata-line,
    a,
    span {
        color: white !important;
    }


    /* YOUTUBE ICONS */

    yt-icon {
        color: white !important;
        fill: white !important;
    }

    svg {
        color: white !important;
    }


    /* HIBISCUS LOGO */

    #logo-icon {
        width: 90px !important;
        height: 45px !important;

        background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAIAAAACACAYAAADDPmHLAAAsSklEQVR42u2deXzdZZX/P+d5vttdc7M1S9t0o4VuFNpCKWBJkAFXrH8RIkSJUqUKFGiRIkSJUqUKFGiRIkSJUqUKFGiRIkSJUqUKFGiRIkSJUqUKFGiRIkSJUqUKFGiRIkSJd4W/H/HXyjCu/mEpQAAAABJRU5ErkJggg==") !important;

        background-size: contain !important;
        background-position: center !important;
        background-repeat: no-repeat !important;

        overflow: visible !important;
    }

    #logo-icon svg {
        opacity: 0 !important;
        visibility: hidden !important;
    }


    /* YOUTUBE LOGO LINK */

    ytd-topbar-logo-renderer {
        background: transparent !important;
    }

    ytd-topbar-logo-renderer a {
        background: transparent !important;
    }


    /* VIDEO THUMBNAILS */

    ytd-thumbnail,
    ytd-thumbnail #thumbnail {
        background: transparent !important;
    }


    /* VIDEO CARDS */

    ytd-rich-item-renderer,
    ytd-rich-grid-media,
    ytd-video-renderer,
    ytd-compact-video-renderer {
        background: transparent !important;
    }


    /* REMOVE EXTRA BACKGROUND LAYERS */

    #chips-wrapper,
    #contents,
    #primary-inner,
    #secondary-inner {
        background: transparent !important;
    }
}
